scripts.preRequest:
// Pre-request Script
const token = rq.environment.get("access_token");
if (token) {
    rq.request.headers["Authorization"] = "Bearer " + token;
}

scripts.postResponse:
// Post-response Script
const responseData = rq.response.json();

if (responseData.access) {
    rq.environment.set("access_token", responseData.access);
    console.log("Access Token saved to environment");
}
if (responseData.refresh) {
    rq.environment.set("refresh_token", responseData.refresh);
    console.log("Refresh Token saved to environment");
}

